(()=>{'use strict';let data=null,loading=null;const URL='ffws-br-2026-s2/home-results.json';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){if(data)return data;if(loading)return loading;loading=fetch(URL,{cache:'no-cache'}).then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status))).then(v=>data=v).catch(()=>data={teams:[],players:[],status:'upcoming'}).finally(()=>loading=null);return loading}function title(id,text){const body=document.getElementById(id),h=body?.closest('.home-widget')?.querySelector('h3');if(h)h.textContent=text}function placeholder(text){return`<tr><td colspan="3" style="padding:24px 14px;text-align:center;color:var(--text-muted);font-weight:800">${esc(text)}</td></tr>`}function renderRows(payload){const teams=document.getElementById('home-tbody-teams'),players=document.getElementById('home-tbody-players');title('home-tbody-teams','🏆 Top 6 Times da WB 2026 S2');title('home-tbody-players','🎯 Top 6 Jogadores da WB 2026 S2');const teamBtn=teams?.closest('.home-widget')?.querySelector('button');if(teamBtn){teamBtn.textContent='VER CLASSIFICAÇÃO →';teamBtn.setAttribute('onclick',"navigate('ffws-br-s2-classificatoria')")}const playerBtn=players?.closest('.home-widget')?.querySelector('button');if(playerBtn){playerBtn.textContent='VER RANKING MVP →';playerBtn.setAttribute('onclick',"navigate('ffws-br-s2-mvp')")}if(teams)teams.innerHTML=(payload.teams||[]).length?(payload.teams||[]).slice(0,6).map((r,i)=>`<tr><td style="color:var(--accent);font-weight:900">${i+1}º</td><td style="text-align:left"><a href="equipe.html?time=${encodeURIComponent(r.team)}" style="color:#fff;text-decoration:none;font-weight:900">${esc(r.short||r.team)}</a><div style="font-size:.75em;color:#888">${Number(r.booyahs||0)} B! • ${Number(r.kills||0)} K</div></td><td style="color:var(--accent);font-weight:900">${Number(r.points||0)}</td></tr>`).join(''):placeholder('A temporada começa em 1º de agosto.');if(players)players.innerHTML=(payload.players||[]).length?(payload.players||[]).slice(0,6).map((r,i)=>`<tr><td style="color:var(--accent);font-weight:900">${i+1}º</td><td style="text-align:left"><a href="jogador.html?jogador=${encodeURIComponent(r.player)}&time=${encodeURIComponent(r.team||'')}" style="color:#fff;text-decoration:none;font-weight:900">${esc(r.player)}</a><div style="font-size:.75em;color:#888">${esc(r.team||'')} • ${Number(r.matches||0)} Q</div></td><td style="color:var(--accent);font-weight:900">${Number(r.kills||0)}</td></tr>`).join(''):placeholder('Ranking disponível após as primeiras quedas.')}window.cffHomeRenderFinalStats=function(){renderRows(data||{teams:[],players:[]});load().then(renderRows);return true};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>load().then(renderRows),{once:true});else load().then(renderRows)})();

;(()=>{
'use strict';
let yearSummary=null,yearPromise=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const teamLogo=name=>({
    'LOUD':'loud 2.webp',
    'TEAM SOLID':'Team Solid 2.webp',
    'INTZ':'Intz 1.webp',
    'FLUXO W7M':'Fluxo 2.webp',
    'FURY UNITED':'https://i.postimg.cc/x8rCzzNm/futd.webp',
    'LOS':'Los.webp',
    'RUSH GAMING':'Rush.webp',
    'AXS FUSION':'AXS BRANCA.webp'
}[String(name||'').toUpperCase()]||'escudo.webp');
const fmtDate=v=>{const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}`:String(v||'')};
async function loadYear(){
    if(yearSummary)return yearSummary;
    if(yearPromise)return yearPromise;
    yearPromise=fetch('novos-torneios/index.json',{cache:'default'})
        .then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status)))
        .then(m=>yearSummary=m?.year2026||null)
        .catch(()=>null)
        .finally(()=>{yearPromise=null});
    return yearPromise;
}
function renderLatest(data){
    const root=document.getElementById('home-year-latest-champions');
    if(!root)return;
    const rows=[...(data?.events||[])].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,4);
    root.innerHTML=rows.length?rows.map(e=>`
        <article class="home-latest-champion">
            <img loading="lazy" decoding="async" src="${esc(teamLogo(e.winner))}" onerror="this.src='escudo.webp'" alt="${esc(e.winner)}">
            <div class="home-latest-champion-copy">
                <span class="home-latest-champion-event">${esc(e.name)}</span>
                <strong>${esc(e.winner)}</strong>
                <small>${fmtDate(e.date)} • MVP ${esc((e.mvp||[]).join(' / '))}</small>
            </div>
        </article>`).join(''):'<div class="home-year-loading">Campeões de 2026 ainda não disponíveis.</div>';
}
function renderTitles(data){
    const root=document.getElementById('home-year-titles-ranking');
    if(!root)return;
    const rows=(data?.titleRanking||[]).slice(0,5);
    root.innerHTML=rows.length?rows.map((r,i)=>`
        <div class="home-year-ranking-row">
            <span class="home-year-ranking-pos">${i+1}</span>
            <div class="home-year-ranking-name">${esc(r.team)}<small>${Number(r.second||0)} vice • ${Number(r.third||0)} top 3</small></div>
            <div class="home-year-ranking-value">${Number(r.first||0)}<small>títulos</small></div>
        </div>`).join(''):'<div class="home-year-loading">Ranking de títulos em atualização.</div>';
}
function renderMvps(data){
    const root=document.getElementById('home-year-mvps-ranking');
    if(!root)return;
    const rows=(data?.mvpRanking||[]).slice(0,5);
    root.innerHTML=rows.length?rows.map((r,i)=>`
        <div class="home-year-ranking-row">
            <span class="home-year-ranking-pos">${i+1}</span>
            <div class="home-year-ranking-name">${esc(r.player)}<small>${Number(r.second||0)} vice • ${Number(r.third||0)} top 3</small></div>
            <div class="home-year-ranking-value">${Number(r.first||0)}<small>MVPs</small></div>
        </div>`).join(''):'<div class="home-year-loading">Ranking de MVPs em atualização.</div>';
}
function renderYearHome(data){if(!data)return;renderLatest(data);renderTitles(data);renderMvps(data)}
window.openCff2026View=function(view='events'){
    window.__cffOt2026PendingView=view;
    const tryOpen=()=>{
        if(typeof window.openOt2026View==='function'){
            window.openOt2026View(view);
            return true;
        }
        return false;
    };
    if(typeof window.navigate==='function')window.navigate('outros-torneios');
    if(tryOpen())return;
    const onModules=()=>{if(tryOpen())document.removeEventListener('cff:modules-loaded',onModules)};
    document.addEventListener('cff:modules-loaded',onModules);
};
const boot=()=>{
    const run=()=>loadYear().then(renderYearHome);
    const target=document.getElementById('home-year-latest-champions');
    if('IntersectionObserver'in window&&target){
        const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();run()}},{rootMargin:'700px 0px'});
        observer.observe(target);
        setTimeout(()=>{observer.disconnect();run()},7000);
    }else setTimeout(run,300);
};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
